// Кейс: .qa/tests/monitoring/MON-028.md (шаги 1–3, 5) · план: .qa/e2e-app/specs/app.md (1.39)
// Экран мониторинга: превью камеры от x=0 до ширины окна (просьба клиента #e1e168, как шаг 2 — #e946f4, подход
// tests/camera-aim/preview-full-width.test.mjs); бейдж «תקין» и «סוללה …%» видны целиком; «מסך מלא» → «יציאה ממסך מלא» → снова во всю ширину.
// Окно тревоги во всю ширину — вручную (тревогу автоматом не вызвать). Запускает мониторинг — только с BANCI_MONITORING=1 (@data).
import { by, assert } from '../../lib/appium.mjs';
import { requireMonitoringOptIn, startMonitoring, endMonitoring } from '../../lib/monitoring.mjs';

export const name = 'Экран мониторинга: превью камеры на всю ширину, «תקין» и «סוללה» видны, «מסך מלא» ↔ «יציאה ממסך מלא» #e1e168 @iphone @app @data';

const inside = (r, x, y) => x >= r.x && x <= r.x + r.width && y >= r.y && y <= r.y + r.height;

/** Превью без имени доступности: самый маленький блок Other/Image высотой ≥ 20% экрана, внутри которого центры
 *  бейджа «תקין» и батареи «סוללה». Не найден — ошибка отбора теста, не баг. */
async function previewRect(app, where) {
  const { width: W, height: H } = await app.windowRect();
  const badge = await (await app.waitFor(by.exact('תקין'), { timeout: 30000, what: `${where}: бейдж «תקין»` })).rect();
  const battery = await (await app.waitFor(by.contains('סוללה'), { what: `${where}: «סוללה …%»` })).rect();
  const bc = [badge.x + badge.width / 2, badge.y + badge.height / 2];
  const pc = [battery.x + battery.width / 2, battery.y + battery.height / 2];
  let best = null;
  for (const e of await app.findAll('type == "XCUIElementTypeOther" OR type == "XCUIElementTypeImage"')) {
    const r = await e.rect();
    if (r.height < H * 0.2 || !inside(r, ...bc) || !inside(r, ...pc)) continue;
    if (!best || r.width * r.height < best.width * best.height) best = r;
  }
  assert(best, `ОШИБКА ТЕСТА (${where}): блок превью с «תקין» и «סוללה» не найден — поправить отбор`);
  assert(best.x <= 1 && best.x + best.width >= W - 1, `${where}: превью на всю ширину: x=${best.x}, ширина=${best.width}, окно=${W} («מה רצוי» #e1e168)`);
  for (const [r, n] of [[badge, '«תקין»'], [battery, '«סוללה»']]) {
    assert(r.x >= 0 && r.x + r.width <= W && r.width > 0, `${where}: ${n} виден целиком: x=${r.x}, ширина=${r.width}, окно=${W}`);
  }
  return best;
}

export default async function (app) {
  requireMonitoringOptIn();
  await startMonitoring(app);
  await previewRect(app, 'экран мониторинга');
  await app.screenshot('e1e168-auto-monitoring');

  await app.tap(by.contains('מסך מלא'), { what: 'кнопка «מסך מלא»' });
  await app.tap(by.contains('יציאה ממסך מלא'), { what: '«יציאה ממסך מלא» в полноэкранном режиме' });
  await app.waitGone(by.contains('יציאה ממסך מלא'), { what: '«יציאה ממסך מלא» после выхода' });
  await previewRect(app, 'после «יציאה ממסך מלא»');
  await app.screenshot('e1e168-auto-after-fullscreen');

  await endMonitoring(app);
}
